  A.part('head', k.Q([0, yb, .14]), () => { k.el(0, yb, .21, .06, .055, .05, c.d, { seg: 10 }); for (const s of [-1, 1]) { k.el(s * .05, yb + .01, .22, .025, .035, .03, 0x1a1008, { seg: 8 }); k.co([s * .02, yb + .05, .25], [s * .06, yb + .16, .38], .004, .0015, c.d, 4); } k.co([0, yb - .03, .25], [0, yb - .06, .32], .01, .004, c.d, 4); });
  const wcol = (u, v) => mix(0xe8e4d0, c.a, 0.12 * (1 - u));
  for (const s of [1, -1]) { A.part(s > 0 ? 'wingL' : 'wingR', k.Q([s * .05, yb + .07, .08]), () => faHiWing(A, s, .05 * S, (yb + .07) * S, .08 * S, .45 * S, .15 * S, .2, wcol, .06)); A.part(s > 0 ? 'wing2L' : 'wing2R', k.Q([s * .05, yb + .06, .0]), () => faHiWing(A, s, .05 * S, (yb + .06) * S, .0, .32 * S, .1 * S, .2, wcol, .05)); }
  const spec = [{ z: .12, kn: [.1, .0, .1], ft: [.14, -.18, .18] }, { z: .06, kn: [.12, .0, .04], ft: [.17, -.18, .06] }, { z: -.0, kn: [.1, .0, -.1], ft: [.13, -.18, -.2] }];
  for (let i = 0; i < 6; i++) { const s = (i & 1) ? -1 : 1, g = spec[i >> 1], root = [s * .04, yb - .06, g.z]; A.part('leg' + i, k.Q(root), () => k.leg([root, [s * g.kn[0], yb - .05, g.z + g.kn[2]], [s * g.ft[0], .0, g.z + g.ft[2]]], [.014, .01, .005], c.d, .02)); }
